static int (*real_withdraw)(account_t *, long);   /* saved before install */

static int audited_withdraw(account_t *a, long amount)
{
    audit_record(AUDIT_ATTEMPT, current_subject(), "withdraw", a->id);
    int rc = real_withdraw(a, amount);
    audit_record(rc == 0 ? AUDIT_OK : AUDIT_FAILED, current_subject(), "withdraw", a->id);
    return rc;
}
